import { cn, Sparkline, type SparklineTone } from '@gntik-ai/ui';
import { TrendDelta, type KpiDelta } from '../shared/TrendDelta';
import { KPI_ITEMS } from './fixtures';

export interface KpiItem {
  id: string;
  label: string;
  /** Pre-formatted value ("38,921", "842 ms"). */
  value: string;
  delta?: KpiDelta;
  /** Optional series for a sparkline under the value, oldest first. */
  trend?: readonly number[];
  trendTone?: SparklineTone;
}

export interface KpiRowProps {
  /** 3–5 tiles read best; more wrap onto a new row. */
  items?: readonly KpiItem[];
  /** `cards` (one card per KPI, default) or `strip` (a single divided card, for page headers). */
  variant?: 'cards' | 'strip';
  /** Draw sparklines for items that have a `trend`. */
  showTrends?: boolean;
  /** Accessible name of the list. */
  label?: string;
  className?: string;
}

const COLS: Record<number, string> = {
  1: 'lg:grid-cols-1',
  2: 'lg:grid-cols-2',
  3: 'lg:grid-cols-3',
  4: 'lg:grid-cols-4',
  5: 'lg:grid-cols-5',
};

/**
 * KPI row: label, big number, delta (direction and sentiment are independent) and an optional
 * Sparkline. A description list, so each label is announced with its value.
 */
export function KpiRow({ items = KPI_ITEMS, variant = 'cards', showTrends = true, label = 'Key metrics', className }: KpiRowProps) {
  const strip = variant === 'strip';
  const cols = COLS[Math.min(items.length, 5)] ?? 'lg:grid-cols-4';
  return (
    <dl
      aria-label={label}
      className={cn(
        'grid grid-cols-1 sm:grid-cols-2',
        cols,
        strip ? 'divide-y divide-border overflow-hidden rounded-xl border border-border bg-card shadow-sm sm:divide-x lg:divide-y-0' : 'gap-4',
        className,
      )}
    >
      {items.map((item) => (
        <div
          key={item.id}
          className={cn('flex min-w-0 flex-col', strip ? 'px-5 py-4' : 'rounded-xl border border-border bg-card p-5 shadow-sm')}
        >
          <dt className={cn('truncate font-medium text-muted-foreground', strip ? 'text-[12px]' : 'text-[13px]')}>{item.label}</dt>
          <dd className="mt-2 flex flex-wrap items-baseline gap-x-2 gap-y-1">
            <span className={cn('font-semibold tracking-tight text-foreground tabular-nums', strip ? 'text-[22px]' : 'text-[26px]')}>
              {item.value}
            </span>
            {item.delta && <TrendDelta {...item.delta} />}
          </dd>
          {item.delta?.note && !strip && <dd className="mt-1 text-[12px] text-muted-foreground">{item.delta.note}</dd>}
          {showTrends && item.trend && item.trend.length > 1 && (
            <dd className="mt-3">
              <Sparkline data={item.trend} label={item.label} area tone={item.trendTone ?? 'primary'} width={240} height={40} className="block h-auto w-full" />
            </dd>
          )}
        </div>
      ))}
    </dl>
  );
}

import type { KpiItem } from './KpiRow';

/** Four project KPIs: note latency and spend — same arrow logic, different sentiment. */
export const KPI_ITEMS: KpiItem[] = [
  {
    id: 'projects',
    label: 'Active projects',
    value: '142',
    delta: { value: '+6', direction: 'up', sentiment: 'positive', note: 'vs. 30 days ago' },
    trend: [128, 130, 131, 133, 134, 137, 139, 142],
  },
  {
    id: 'requests',
    label: 'Requests · 24h',
    value: '38,921',
    delta: { value: '+12.4%', direction: 'up', sentiment: 'positive', note: 'vs. previous 24h' },
    trend: [31, 34, 33, 38, 36, 41, 39],
  },
  {
    id: 'latency',
    label: 'Avg latency',
    value: '842 ms',
    delta: { value: '−8.1%', direction: 'down', sentiment: 'positive', note: 'vs. previous 24h' },
    trend: [910, 884, 902, 861, 852, 848, 842],
  },
  {
    id: 'spend',
    label: 'Spend · month to date',
    value: '$18,204',
    delta: { value: '+4.2%', direction: 'up', sentiment: 'negative', note: 'vs. last month' },
    trend: [12.1, 13.4, 14.2, 15.0, 16.3, 17.1, 18.2],
    trendTone: 'warning',
  },
];

import { cn } from '@gntik-ai/ui';

/** Arrow shape of a change. */
export type DeltaDirection = 'up' | 'down' | 'flat';
/** Whether the change is good, bad or neither — independent of its direction (lower latency is good). */
export type DeltaSentiment = 'positive' | 'negative' | 'neutral';

export interface KpiDelta {
  /** Display text, e.g. "+12.4%". */
  value: string;
  direction: DeltaDirection;
  sentiment: DeltaSentiment;
  /** Comparison context, e.g. "vs. previous 24h". */
  note?: string;
}

const SENTIMENT_CLASS: Record<DeltaSentiment, string> = {
  positive: 'text-success-text',
  negative: 'text-destructive-text',
  neutral: 'text-muted-foreground',
};

const DIRECTION_TEXT: Record<DeltaDirection, string> = { up: 'Increased by', down: 'Decreased by', flat: 'Unchanged:' };
const SENTIMENT_TEXT: Record<DeltaSentiment, string> = { positive: 'favourable', negative: 'unfavourable', neutral: '' };

export interface TrendDeltaProps extends KpiDelta {
  className?: string;
}

/**
 * Mono delta with a triangle: the arrow follows `direction`, the colour follows `sentiment`.
 * Screen readers get the direction and sentiment in words.
 */
export function TrendDelta({ value, direction, sentiment, className }: TrendDeltaProps) {
  const sr = [DIRECTION_TEXT[direction], value, SENTIMENT_TEXT[sentiment] && `(${SENTIMENT_TEXT[sentiment]})`].filter(Boolean).join(' ');
  return (
    <span
      data-sentiment={sentiment}
      className={cn('inline-flex items-center gap-1 font-mono text-[12px] font-medium tabular-nums', SENTIMENT_CLASS[sentiment], className)}
    >
      <svg width="9" height="9" viewBox="0 0 10 10" aria-hidden className="shrink-0">
        {direction === 'up' && <path d="M5 1.5 9 8.5H1z" fill="currentColor" />}
        {direction === 'down' && <path d="M5 8.5 1 1.5h8z" fill="currentColor" />}
        {direction === 'flat' && <path d="M1 4h8v2H1z" fill="currentColor" />}
      </svg>
      <span aria-hidden>{value}</span>
      <span className="sr-only">{sr}</span>
    </span>
  );
}
